import { MeshBasicNodeMaterial, PlaneGeometry } from 'three/webgpu';
import { texture, uv, vec2, vec4 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // Read text content
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = items.find(item => item.role === 'headline') || items[0];
  const headlineText = headlineItem?.text || 'Collection 1';
  const fontSize = headlineItem?.typography?.fontSize || 39;

  // Atlas region (source rect: x=0, y=0, width=512, height=320)
  const atlasWidth = 512;
  const atlasHeight = 320;
  const aspectRatio = atlasWidth / atlasHeight; // 1.6

  // Create the plane geometry with proper aspect ratio
  const planeWidth = 2.0;
  const planeHeight = planeWidth / aspectRatio;
  const geometry = new PlaneGeometry(planeWidth, planeHeight);

  // Load the texture with atlas UV mapping
  const texPromise = ctx.textureLoader.loadTexture(config.imageUrl);

  // Create material with atlas UV offset
  const material = new MeshBasicNodeMaterial({
    transparent: true,
    side: THREE.DoubleSide,
    depthWrite: false
  });

  // Apply texture with atlas region offset and scale
  texPromise.then((tex) => {
    // Calculate UV offset/scale for atlas region
    // Source rect: 0, 0, 512, 320 — full texture area in this case
    const uOffset = 0;
    const vOffset = 0;
    const uScale = 1;
    const vScale = 1;

    material.map = tex;
    material.map.wrapS = THREE.ClampToEdgeWrapping;
    material.map.wrapT = THREE.ClampToEdgeWrapping;
    material.map.repeat.set(uScale, vScale);
    material.map.offset.set(uOffset, vOffset);
    material.needsUpdate = true;
  });

  // Create the mesh
  const mesh = new THREE.Mesh(geometry, material);

  // Create a group to hold mesh and text
  const group = new THREE.Group();
  group.add(mesh);

  // Add text label using font atlas
  const textConfig = {
    fontSize: fontSize,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: 0.05 * fontSize // letterSpacing 0.05em
  };

  const textMesh = ctx.fontAtlas.createText(headlineText, textConfig);
  if (textMesh) {
    // Position text below the card
    textMesh.position.set(0, -planeHeight/2 - 0.25, 0.01);
    group.add(textMesh);
  }

  // Apply scene placement from config
  if (config.scenePosition) {
    group.position.set(
      config.scenePosition.x ?? -3.2,
      config.scenePosition.y ?? 1,
      config.scenePosition.z ?? 0.06
    );
    if (config.scenePosition.rotation) {
      group.rotation.set(
        config.scenePosition.rotation.x ?? 0,
        config.scenePosition.rotation.y ?? 0,
        config.scenePosition.rotation.z ?? 0
      );
    }
    if (config.scenePosition.scale) {
      const s = config.scenePosition.scale;
      group.scale.set(
        typeof s === 'number' ? s : (s.x ?? 1),
        typeof s === 'number' ? s : (s.y ?? 1),
        typeof s === 'number' ? s : (s.z ?? 1)
      );
    }
  }

  // Billboarding — track camera and rotate to face it
  const billboardHandler = (camera) => {
    const lookTarget = new THREE.Vector3();
    camera.getWorldPosition(lookTarget);
    group.lookAt(lookTarget);
    // Reset rotation on Z axis to keep upright
    group.rotation.z = 0;
  };

  // Store billboard controller in userData
  group.userData.billboard = billboardHandler;

  // Event handlers (none specified, but provide empty handlers)
  group.userData.handlers = {};

  // Cleanup function
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (material.map) {
      material.map.dispose();
    }
    // Kill any GSAP timelines
    if (group.userData._timelines) {
      group.userData._timelines.forEach(t => t.kill());
    }
    // Remove from parent if exists
    if (group.parent) {
      group.parent.remove(group);
    }
  };

  return group;
}
